"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[8495],{10998(t,e,a){a.r(e),a.d(e,{comp:()=>d,data:()=>c});var n=a(20641);const o=a.p+"assets/img/admin-seller-vacation-settings.9117c70a.png",i=a.p+"assets/img/admin-vacations-list.4c969001.png",s=a.p+"assets/img/admin-vacation-edit.2f7d6d96.png",l={class:"hint-container tip"},r={},d=(0,a(66262).A)(r,[["render",function(t,e){const a=(0,n.g2)("RouteLink");return(0,n.uX)(),(0,n.CE)("div",null,[e[4]||(e[4]=(0,n.Fv)('<h1 id="configuration-–-vacation-settings" tabindex="-1"><a class="header-anchor" href="#configuration-–-vacation-settings"><span>Configuration – Vacation Settings</span></a></h1><p>The <strong>Vacation Settings</strong> tab allows marketplace administrators to configure global vacation policies, customize closed-store button labels, control product visibility, and manage seller vacation schedules.</p><p>The marketplace admin can access and configure this section from:</p><p><strong>Marketplace &gt; Settings &gt; Vacation</strong></p><p><strong>Direct Admin Navigation URLs</strong>:</p><ul><li><strong>Vacation Settings Tab</strong>: <code>wp-admin/admin.php?page=wk-marketplace-settings&amp;tab=seller_vacation</code></li><li><strong>Vendors on Vacation Management</strong>: <code>wp-admin/admin.php?page=wk-marketplace-vacations</code></li></ul><p><a class="doc-image-link" href="./assets/admin-seller-vacation-settings.png"><img src="'+o+'" alt="Admin Vacation Settings"></a></p><hr><h2 id="vacation-settings-overview" tabindex="-1"><a class="header-anchor" href="#vacation-settings-overview"><span>Vacation Settings Overview</span></a></h2><ul><li>Globally enable or disable the Vacation feature across the entire marketplace.</li><li>Customize the Add to Cart button text displayed on single product detail pages when a store is closed.</li><li>Customize the Add to Cart button label on category archives, shop loops, and catalog listing pages.</li><li>Optionally hide products belonging to closed vendors from catalog listings, category archives, and search results.</li><li>Automated daily scheduled task that automatically ends expired vacations and restores vendor stores.</li><li>Centralized administrator control to monitor, enable, disable, edit, or delete any vendor&#39;s vacation schedule.</li></ul>',10)),(0,n.Lk)("div",l,[e[3]||(e[3]=(0,n.Lk)("p",{class:"hint-container-title"},"Vendor Guide Reference",-1)),(0,n.Lk)("p",null,[e[1]||(e[1]=(0,n.eW)("To learn how vendors schedule and manage their holidays from the front-end seller dashboard, refer to the ")),(0,n.bF)(a,{to:"/documentation/vendor-vacation.html"},{default:(0,n.k6)(()=>e[0]||(e[0]=[(0,n.eW)("Vacation Mode Guide")])),_:1}),e[2]||(e[2]=(0,n.eW)("."))])]),e[5]||(e[5]=(0,n.Fv)('<hr><h2 id="admin-vacation-settings-summary" tabindex="-1"><a class="header-anchor" href="#admin-vacation-settings-summary"><span>Admin Vacation Settings Summary</span></a></h2><p>The table below provides a quick reference for each setting available on the <strong>Vacation</strong> configuration tab:</p><table><thead><tr><th style="text-align:left;">Setting Label</th><th style="text-align:left;">Input Type</th><th style="text-align:left;">Default Setting</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enable Vacation</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Enabled (Checked)</td><td style="text-align:left;">Allows vendors to use the Vacation feature. When disabled, the Vacation tab is hidden from vendor dashboards and no vacation restrictions are enforced on the storefront.</td></tr><tr><td style="text-align:left;"><strong>Single Page &#39;Add to Cart&#39; Button Label</strong></td><td style="text-align:left;">Text Field (Max 30 chars)</td><td style="text-align:left;"><code>Shop Closed</code></td><td style="text-align:left;">Text displayed on the disabled Add to Cart button on the single product page when the vendor&#39;s shop is closed.</td></tr><tr><td style="text-align:left;"><strong>Archive Page &#39;Add to Cart&#39; Button Label</strong></td><td style="text-align:left;">Text Field (Max 60 chars)</td><td style="text-align:left;"><code>Currently Closed</code></td><td style="text-align:left;">Text displayed on the Add to Cart button across shop, category archive, and catalog listing pages when the shop is closed.</td></tr><tr><td style="text-align:left;"><strong>Hide Closed Products</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Disabled (Unchecked)</td><td style="text-align:left;">Hides closed-store products from shop, archive, and search results. Products remain visible on the vendor&#39;s profile page. Applies when a vendor blocks purchases during vacation.</td></tr><tr><td style="text-align:left;"><strong>Automated Expiry Task</strong></td><td style="text-align:left;">Scheduled Task</td><td style="text-align:left;">Daily Automatic Execution</td><td style="text-align:left;">A built-in daily scheduled task that checks vacation end dates, ends expired vacations automatically, and reopens those vendor stores.</td></tr><tr><td style="text-align:left;"><strong>Save Changes</strong></td><td style="text-align:left;">Primary Button</td><td style="text-align:left;">Click to Save</td><td style="text-align:left;">Immediately applies and stores the updated marketplace-wide vacation settings.</td></tr></tbody></table><hr><h2 id="admin-vacation-settings" tabindex="-1"><a class="header-anchor" href="#admin-vacation-settings"><span>Admin Vacation Settings</span></a></h2><h3 id="enable-vacation" tabindex="-1"><a class="header-anchor" href="#enable-vacation"><span>Enable Vacation</span></a></h3><ul><li><strong>Setting Type</strong>: Checkbox</li><li><strong>Default State</strong>: Enabled (Checked)</li><li><strong>Live Description</strong>: <em>&quot;Allow vendors to use the Vacation feature. When disabled, the Vacation tab is hidden from vendors and no vacation rules are enforced on the storefront.&quot;</em></li></ul><h4 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works"><span>How It Works:</span></a></h4><ul><li><strong>When Enabled</strong>: Vendors see the <strong>Vacation</strong> menu tab in their seller dashboard. Vendors can schedule vacations, configure custom notices, and manage store closure rules.</li><li><strong>When Disabled</strong>: The Vacation section is hidden from all vendor dashboards. Even if a vendor had previously saved a vacation period, no storefront restrictions (such as disabled Add to Cart buttons or product hiding) are enforced.</li></ul><hr><h3 id="single-page-add-to-cart-button-label" tabindex="-1"><a class="header-anchor" href="#single-page-add-to-cart-button-label"><span>Single Page &#39;Add to Cart&#39; Button Label</span></a></h3><ul><li><strong>Setting Type</strong>: Text Field (Maximum 30 characters)</li><li><strong>Default Value</strong>: <code>Shop Closed</code></li><li><strong>Live Description</strong>: <em>&quot;Text on the disabled Add to Cart button on the single product page when the shop is closed. Maximum 30 characters.&quot;</em></li></ul><h4 id="how-it-works-1" tabindex="-1"><a class="header-anchor" href="#how-it-works-1"><span>How It Works:</span></a></h4><ul><li>When a vendor&#39;s vacation is active and configured to prevent sales, the standard <strong>Add to Cart</strong> button on the product details page (<code>PDP</code>) is disabled.</li><li>The button text is replaced with this configured label (for example, <em>Shop Closed</em>, <em>On Vacation</em>, or <em>Temporarily Unavailable</em>).</li><li>This clearly informs shoppers that the item cannot be purchased until the vendor returns.</li></ul><hr><h3 id="archive-page-add-to-cart-button-label" tabindex="-1"><a class="header-anchor" href="#archive-page-add-to-cart-button-label"><span>Archive Page &#39;Add to Cart&#39; Button Label</span></a></h3><ul><li><strong>Setting Type</strong>: Text Field (Maximum 60 characters)</li><li><strong>Default Value</strong>: <code>Currently Closed</code></li><li><strong>Live Description</strong>: <em>&quot;Text on the Add to Cart button on shop / archive / listing pages when the shop is closed. Maximum 60 characters.&quot;</em></li></ul><h4 id="how-it-works-2" tabindex="-1"><a class="header-anchor" href="#how-it-works-2"><span>How It Works:</span></a></h4><ul><li>On catalog listing pages, category archives, tag results, and the main shop page (<code>PLP</code>), the Add to Cart button for products from closed vendors is updated to this custom label.</li><li>This prevents customers from quick-adding products to their shopping cart from archive loops while a vendor is away.</li></ul><hr><h3 id="hide-closed-products" tabindex="-1"><a class="header-anchor" href="#hide-closed-products"><span>Hide Closed Products</span></a></h3><ul><li><strong>Setting Type</strong>: Checkbox</li><li><strong>Default State</strong>: Disabled (Unchecked)</li><li><strong>Live Description</strong>: <em>&quot;Hide closed-store products from shop, archive and search results. Products stay visible on the vendor profile page. Applies only when a vendor blocks purchases during off hours.&quot;</em></li></ul><h4 id="how-it-works-3" tabindex="-1"><a class="header-anchor" href="#how-it-works-3"><span>How It Works:</span></a></h4><ul><li><strong>When Enabled</strong>: Products belonging to vendors who are currently on vacation (with sales prevented) are filtered out from the main WooCommerce catalog, product category archives, and search results. Customers browsing the catalog only see purchasable items. Products remain visible when browsing the vendor&#39;s dedicated store profile page.</li><li><strong>When Disabled</strong>: Products from vacationing vendors remain visible in catalog and search results, but their Add to Cart button reflects the configured archive closed label and purchases are blocked.</li></ul><div class="hint-container tip"><p class="hint-container-title">Profile Visibility Note</p><p>Even when <strong>Hide Closed Products</strong> is enabled, products continue to display on the vendor&#39;s own store profile page (<code>/shop/vendor-name/</code>). This allows interested buyers to browse the seller&#39;s catalog and read the vacation return announcement.</p></div><hr><h3 id="automated-vacation-expiry-task" tabindex="-1"><a class="header-anchor" href="#automated-vacation-expiry-task"><span>Automated Vacation Expiry Task</span></a></h3><ul><li><strong>Execution</strong>: Daily Automatic Background Task</li><li><strong>Live Note</strong>: <em>&quot;A daily scheduled task ends expired vacations automatically and reopens those shops.&quot;</em></li></ul><h4 id="how-it-works-4" tabindex="-1"><a class="header-anchor" href="#how-it-works-4"><span>How It Works:</span></a></h4><ul><li>The marketplace runs an automated daily scheduled task.</li><li>It scans all active vacation records and checks whether the current date has passed the vendor&#39;s configured <strong>To</strong> date.</li><li>When an expired vacation is detected, the system marks the vacation as <strong>Expired</strong>, removes all purchase blocks, and reopens the store automatically without requiring manual action by the vendor or administrator.</li></ul><hr><h2 id="admin-controls-for-vacation-mode" tabindex="-1"><a class="header-anchor" href="#admin-controls-for-vacation-mode"><span>Admin Controls for Vacation Mode</span></a></h2><p>Admins have full control over the Vacation Mode feature:</p><ul><li>Enable or disable the vacation feature globally.</li><li>Edit a specific vendor&#39;s vacation schedule and settings.</li><li>Bulk enable, disable, or delete vacations from a sortable list in the admin panel.</li><li>Customize the vendor dashboard URL endpoint for vacation.</li></ul><h3 id="managing-vendors-on-vacation" tabindex="-1"><a class="header-anchor" href="#managing-vendors-on-vacation"><span>Managing Vendors on Vacation</span></a></h3><p>Marketplace administrators can monitor all seller vacations from:</p><p><strong>Marketplace &gt; Vacations</strong></p><p><strong>Direct Admin URL</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">wp-admin/admin.php?page=wk-marketplace-vacations</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><a class="doc-image-link" href="./assets/admin-vacations-list.png"><img src="'+i+'" alt="Admin Vendors on Vacation List"></a></p><h4 id="list-features" tabindex="-1"><a class="header-anchor" href="#list-features"><span>List Features:</span></a></h4><ul><li><strong>Status Filter Tabs</strong>: Filter vacation records by <strong>Active</strong>, <strong>Expired</strong>, or <strong>All</strong>.</li><li><strong>Information Columns</strong>: <ul><li><strong>Shop</strong>: Name of the vendor&#39;s shop with quick action links (<code>Edit</code>).</li><li><strong>Vendor</strong>: Display name and email address of the seller account.</li><li><strong>From</strong>: Start date of the scheduled vacation.</li><li><strong>To</strong>: Return date when the vacation concludes.</li><li><strong>Behavior</strong>: Indicates whether the vendor chose to <em>Prevent sales</em> or <em>Keep shop open</em>.</li><li><strong>Status</strong>: Current status of the vacation (<em>Active</em>, <em>Expired</em>, or <em>Disabled</em>).</li></ul></li><li><strong>Bulk Actions</strong>: Select multiple vendors and apply <strong>Enable</strong>, <strong>Disable</strong>, or <strong>Delete</strong> with a single click.</li></ul><hr><h3 id="editing-a-vendor-s-vacation-from-admin" tabindex="-1"><a class="header-anchor" href="#editing-a-vendor-s-vacation-from-admin"><span>Editing a Vendor&#39;s Vacation from Admin</span></a></h3><p>Administrators can directly inspect and modify any vendor&#39;s vacation schedule by navigating to:</p><p><strong>Marketplace &gt; Vacations &gt; Edit (Under Shop Name)</strong></p><p><strong>Direct Admin Edit URL</strong>:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">wp-admin/admin.php?page=wk-marketplace-vacations&amp;section=edit&amp;vacation_id={ID}</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><a class="doc-image-link" href="./assets/admin-vacation-edit.png"><img src="'+s+'" alt="Admin Edit Vacation"></a></p><p>The Edit Vacation screen provides full administrative control over a seller&#39;s vacation dates, sales behavior, and customer-facing notice.</p><h4 id="edit-vacation-settings-summary" tabindex="-1"><a class="header-anchor" href="#edit-vacation-settings-summary"><span>Edit Vacation Settings Summary</span></a></h4><p>The table below outlines every parameter and input control available on the Edit Vacation screen:</p><table><thead><tr><th style="text-align:left;">Setting Label</th><th style="text-align:left;">Input Type</th><th style="text-align:left;">Default / Values</th><th style="text-align:left;">Description &amp; Operational Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Vendor</strong></td><td style="text-align:left;">Read-only Display</td><td style="text-align:left;">Shop Name &amp; Email</td><td style="text-align:left;">Displays the seller shop name along with their account email address (e.g., <code>Lumen Beauty (hello@lumenbeauty.test)</code>).</td></tr><tr><td style="text-align:left;"><strong>Enable vacation mode</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Checked / Unchecked</td><td style="text-align:left;">Admin override switch. Checking this immediately places the vendor into vacation mode across storefront pages.</td></tr><tr><td style="text-align:left;"><strong>Schedule vacation mode</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Checked / Unchecked</td><td style="text-align:left;">When checked, displays calendar date pickers to constrain the vacation to a specific date range.</td></tr><tr><td style="text-align:left;"><strong>Schedule: From</strong></td><td style="text-align:left;">Date Picker</td><td style="text-align:left;">Date (<code>YYYY-MM-DD</code>)</td><td style="text-align:left;">Starting date when vacation mode begins taking effect. Required if schedule mode is active.</td></tr><tr><td style="text-align:left;"><strong>Schedule: To</strong></td><td style="text-align:left;">Date Picker</td><td style="text-align:left;">Date (<code>YYYY-MM-DD</code>)</td><td style="text-align:left;">Concluding date of the vacation. Must be identical to or later than the <strong>From</strong> date.</td></tr><tr><td style="text-align:left;"><strong>During the vacation period</strong></td><td style="text-align:left;">Checkbox</td><td style="text-align:left;">Prevent sales (Default)</td><td style="text-align:left;">Controls purchasing behavior: Check to <em>&quot;Prevent sales during vacation&quot;</em> (blocks cart additions). Uncheck to keep the shop open for purchases while showing the message.</td></tr><tr><td style="text-align:left;"><strong>Vacation message</strong></td><td style="text-align:left;">Rich Text Editor</td><td style="text-align:left;">Formatted Text / HTML</td><td style="text-align:left;">Custom announcement shown to customers on the vendor&#39;s profile banner and product pages while vacation mode is active.</td></tr><tr><td style="text-align:left;"><strong>Update Vacation</strong></td><td style="text-align:left;">Primary Button</td><td style="text-align:left;">Click to Save</td><td style="text-align:left;">Applies the updated settings to the vendor&#39;s store immediately.</td></tr><tr><td style="text-align:left;"><strong>Back to Vendors</strong></td><td style="text-align:left;">Button Link</td><td style="text-align:left;">Return to List</td><td style="text-align:left;">Cancels editing and returns the administrator to the main <code>Marketplace &gt; Vacations</code> list.</td></tr></tbody></table><h4 id="detailed-edit-vacation-field-breakdown" tabindex="-1"><a class="header-anchor" href="#detailed-edit-vacation-field-breakdown"><span>Detailed Edit Vacation Field Breakdown:</span></a></h4><ol><li><p><strong>Vendor Information</strong>:</p><ul><li>Identifies the specific vendor whose store is being managed. Displays both the public shop name and the registered user email address.</li></ul></li><li><p><strong>Enable vacation mode</strong>:</p><ul><li>Allows administrators to instantly activate or deactivate vacation mode for this vendor, regardless of whether the vendor turned it on themselves.</li><li>When unchecked, the vendor&#39;s shop is immediately reopened and product purchase buttons return to normal.</li></ul></li><li><p><strong>Schedule vacation mode (From &amp; To Dates)</strong>:</p><ul><li>When checked, the schedule date inputs expand.</li><li><strong>Validation Rules</strong>: <ul><li>If scheduled mode is active, both <strong>From</strong> and <strong>To</strong> dates are required. If either date is missing, the system displays: <em>&quot;Please provide both From and To dates for a scheduled vacation.&quot;</em></li><li>The <strong>To</strong> date cannot be earlier than the <strong>From</strong> date. If an invalid date range is entered, the system prompts: <em>&quot;The To date must be the same as or after the From date.&quot;</em></li></ul></li></ul></li><li><p><strong>During the vacation period (Sales Behavior)</strong>:</p><ul><li><strong>Prevent Sales (Checked)</strong>: Enforces purchasing blocks. On single product pages, the Add to Cart button is disabled with the configured closed label (e.g., <code>Shop Closed</code>). Archive pages reflect the closed state or hide the product based on marketplace settings.</li><li><strong>Keep Shop Open (Unchecked)</strong>: The store continues taking customer orders. The custom vacation message still displays on the storefront, setting shopper expectations about fulfillment timelines while allowing ongoing revenue.</li></ul></li><li><p><strong>Vacation message Editor</strong>:</p><ul><li>Uses the standard WordPress text editor with <strong>Visual</strong> and <strong>Code</strong> tabs.</li><li>Administrators can format text (bold, italic, bullet lists, blockquotes) and insert links.</li><li>This message renders prominently in the storefront vacation announcement banner on the vendor&#39;s profile page and individual product detail pages.</li></ul></li><li><p><strong>Saving Changes</strong>:</p><ul><li>Clicking <strong>Update Vacation</strong> saves the modified vacation schedule and immediately applies the new rules across the marketplace storefront.</li><li>A success alert (<em>&quot;1 vacation updated.&quot;</em>) confirms the update.</li></ul></li></ol><hr><h3 id="customizing-the-vacation-endpoint-url" tabindex="-1"><a class="header-anchor" href="#customizing-the-vacation-endpoint-url"><span>Customizing the Vacation Endpoint URL</span></a></h3><p>Store administrators can customize the vendor dashboard URL slug for the vacation section from:</p><p><strong>Marketplace &gt; Settings &gt; Endpoints</strong></p><ul><li><strong>Setting Name</strong>: <strong>Vacation</strong></li><li><strong>Default URL Slug</strong>: <code>vendor-vacation</code></li><li><strong>Vendor Dashboard Page</strong>: <code>https://example.com/my-account/vendor-vacation/</code></li></ul><p>This allows administrators to tailor the dashboard URL structure to match their marketplace branding or multilingual setup without affecting vacation rules or seller data.</p>',62))])}]]),c=JSON.parse('{"path":"/documentation/admin-vacation-setting.html","title":"Configuration – Vacation Settings","lang":"en-US","frontmatter":{"title":"Configuration – Vacation Settings","description":"Configure vendor vacation settings in WooCommerce Multi-Vendor Marketplace. Manage vacation mode, custom Add to Cart button labels, closed product visibility, automated shop reopening, and vendor schedules.","head":[["meta",{"name":"keywords","content":"woocommerce marketplace vacation settings, admin vacation settings, seller vacation configuration, hide closed products woocommerce, store closed button label woocommerce, vendor vacation admin"}],["meta",{"property":"og:title","content":"Configuration – Vacation Settings | WooCommerce Multi-Vendor Marketplace"}],["meta",{"property":"og:description","content":"Configure vendor vacation settings in WooCommerce Multi-Vendor Marketplace. Manage vacation mode, custom Add to Cart button labels, closed product visibility, automated shop reopening, and vendor schedules."}],["meta",{"property":"og:type","content":"article"}]]},"headers":[{"level":2,"title":"Vacation Settings Overview","slug":"vacation-settings-overview","link":"#vacation-settings-overview","children":[]},{"level":2,"title":"Admin Vacation Settings Summary","slug":"admin-vacation-settings-summary","link":"#admin-vacation-settings-summary","children":[]},{"level":2,"title":"Admin Vacation Settings","slug":"admin-vacation-settings","link":"#admin-vacation-settings","children":[{"level":3,"title":"Enable Vacation","slug":"enable-vacation","link":"#enable-vacation","children":[]},{"level":3,"title":"Single Page \'Add to Cart\' Button Label","slug":"single-page-add-to-cart-button-label","link":"#single-page-add-to-cart-button-label","children":[]},{"level":3,"title":"Archive Page \'Add to Cart\' Button Label","slug":"archive-page-add-to-cart-button-label","link":"#archive-page-add-to-cart-button-label","children":[]},{"level":3,"title":"Hide Closed Products","slug":"hide-closed-products","link":"#hide-closed-products","children":[]},{"level":3,"title":"Automated Vacation Expiry Task","slug":"automated-vacation-expiry-task","link":"#automated-vacation-expiry-task","children":[]}]},{"level":2,"title":"Admin Controls for Vacation Mode","slug":"admin-controls-for-vacation-mode","link":"#admin-controls-for-vacation-mode","children":[{"level":3,"title":"Managing Vendors on Vacation","slug":"managing-vendors-on-vacation","link":"#managing-vendors-on-vacation","children":[]},{"level":3,"title":"Editing a Vendor\'s Vacation from Admin","slug":"editing-a-vendor-s-vacation-from-admin","link":"#editing-a-vendor-s-vacation-from-admin","children":[]},{"level":3,"title":"Customizing the Vacation Endpoint URL","slug":"customizing-the-vacation-endpoint-url","link":"#customizing-the-vacation-endpoint-url","children":[]}]}],"git":{},"filePathRelative":"documentation/admin-vacation-setting.md"}')}}]);